/**
 * Loading the audio library into Foundry — design/audio-system.md §3.
 *
 * Four files, three owners, one combined view (core/audio-library.mjs
 * #buildLibraryIndex):
 *   data/campaign/audio/library.json   generated by tools/audio-pipeline
 *   data/campaign/audio/review.json    human classification decisions
 *   data/campaign/campaign/asset-registry.json  reservations
 *   data/campaign/audio/{soundscapes,cues}/*.json  authored direction
 *
 * (The doubled "campaign" segment is real: sync-campaign-data.mjs stages the
 * repo's `data/<dir>/` into the module's `data/campaign/<dir>/`.)
 *
 * Everything is loaded once per client session and cached. `refreshAudio()`
 * drops the cache — the Sound Desk offers it, so a GM who has just re-run the
 * pipeline and re-synced does not have to reload the whole world.
 */

import { buildLibraryIndex } from "../core/audio-library.mjs";
import { validateCue, validateSoundscape } from "../core/audio-director.mjs";
import { fetchModuleJson, listModuleJsonIds } from "./io.mjs";

const DATA_ROOT = "data/campaign";
const AUDIO_DIR = `${DATA_ROOT}/audio`;

let cache = null;

async function fetchOptional(path, fallback) {
  try {
    return await fetchModuleJson(path);
  } catch (err) {
    console.log(`Blank Inheritance | ${path} not present (${err?.message ?? err})`);
    return fallback;
  }
}

async function loadDirectory(dir) {
  const ids = await listModuleJsonIds(`${AUDIO_DIR}/${dir}`);
  const docs = [];
  for (const id of ids) {
    const doc = await fetchOptional(`${AUDIO_DIR}/${dir}/${id}.json`, null);
    if (doc) docs.push(doc);
  }
  return docs;
}

/**
 * The whole audio world: the index, the authored direction, and every problem
 * found while loading it. Problems are collected, never thrown — one bad cue
 * file must not take the sound desk down with it mid-session.
 */
export async function loadAudio({ force = false } = {}) {
  if (cache && !force) return cache;
  const [library, review, registry, soundscapes, cues] = await Promise.all([
    fetchOptional(`${AUDIO_DIR}/library.json`, { assets: [] }),
    fetchOptional(`${AUDIO_DIR}/review.json`, { decisions: {} }),
    fetchOptional(`${DATA_ROOT}/campaign/asset-registry.json`, { assets: [] }),
    loadDirectory("soundscapes"),
    loadDirectory("cues")
  ]);

  const index = buildLibraryIndex({ library, review, registry });
  const soundscapeIds = new Set(soundscapes.map((s) => s.id));
  const problems = [...index.problems.map((p) => p.message)];
  for (const doc of soundscapes) problems.push(...validateSoundscape(doc, index));
  for (const doc of cues) problems.push(...validateCue(doc, index, soundscapeIds));

  cache = {
    index,
    library,
    review,
    registry,
    soundscapes: new Map(soundscapes.map((s) => [s.id, s])),
    cues: new Map(cues.map((c) => [c.id, c])),
    problems,
    root: library.root ?? "blank-inheritance-audio",
    loadedAt: Date.now()
  };
  if (problems.length) console.warn(`Blank Inheritance | Audio library loaded with ${problems.length} problem(s):`, problems);
  return cache;
}

export function cachedAudio() {
  return cache;
}

export async function refreshAudio() {
  cache = null;
  return loadAudio({ force: true });
}

/** The URL a client fetches an asset from. */
export function srcFor(asset, root = cache?.root ?? "blank-inheritance-audio") {
  if (!asset?.encode?.path) return null;
  return `${root}/${asset.encode.path}`;
}

/** Look one asset up in the loaded index. */
export function assetFor(id) {
  return cache?.index?.assets?.get?.(id) ?? null;
}
